int crossnz=0;for(int r=rank;r<RR;r++)for(int k=0;k<NC;k++)if(pairs[k].first!=pairs[k].second&&mat[r][G+1+k])crossnz++;ofstream co("cokernel_quadratics.bin",ios::binary);for(int r=rank;r<RR;r++)co.write((char*)&mat[r][G],4*(NC+1));co.close();
int unknown=crossnz?NC:F;vector<vector<U>>sys(RR-rank,vector<U>(unknown+1));for(int i=rank;i<RR;i++){sys[i-rank][unknown]=mat[i][G];for(int j=0;j<unknown;j++)sys[i-rank][j]=mat[i][G+1+(crossnz?j:diags[j])];}vector<int>p2;int rk=0;for(int j=0;j<unknown;j++){int r=rk;while(r<(int)sys.size()&&!sys[r][j])r++;if(r==(int)sys.size())continue;swap(sys[r],sys[rk]);U f=inv(sys[rk][j]);for(int k=j;k<=unknown;k++)sys[rk][k]=mul(sys[rk][k],f);for(int i=rk+1;i<(int)sys.size();i++)if(sys[i][j]){f=sys[i][j];for(int k=j;k<=unknown;k++)sys[i][k]^=mul(f,sys[rk][k]);}p2.push_back(j);rk++;}bool inconsistent=false;for(int i=rk;i<(int)sys.size();i++)if(sys[i][unknown])inconsistent=true;
